UPDATE public.platform_settings
SET value = value || E'\n\nالقسم السادس: تعديلات إضافية على شروط الاستخدام\n\n20. احتساب نسبة المعلم\n20.1. تُحتسب نسبة المعلم من صافي إيرادات البيع بعد خصم قيمة ضريبة القيمة المضافة.\n\n21. سعر المادة وضريبة القيمة المضافة\n21.1. سعر المادة المعروض على المنصة شامل لقيمة ضريبة القيمة المضافة.\n\n22. مسؤولية الأخطاء العلمية\n22.1. لا تتحمل المنصة مسؤولية أي خطأ علمي ينتج عن شرح المعلم.\n22.2. يلتزم المعلم بتصحيح أي خطأ علمي في محتواه وتحمّل المسؤولية الكاملة عنه.\n\n23. استرداد المبالغ وإلغاء الاشتراك\n23.1. يتم التحقق من الحركة المالية عند استرداد الطالب للمبلغ في حالة إلغاء اشتراكه.\n23.2. يخضع الاسترداد لشروط التسجيل المعتمدة في المنصة.'
WHERE key = 'instructor_policies_ar';